using System;using System.IO;using System.Drawing;using System.Windows.Forms;using System.Diagnostics;
class Pds:Form{
 PhoneDeskConfiguration config;ComboBox[] models=new ComboBox[5],colors=new ComboBox[5];NumericUpDown[] scales=new NumericUpDown[5];CheckBox[] enabled=new CheckBox[5];
 public Pds(){Text="Phone Desk Settings";Font=new Font("Segoe UI",10);ClientSize=new Size(760,470);MinimumSize=Size;StartPosition=FormStartPosition.CenterScreen;BackColor=Color.FromArgb(24,30,43);ForeColor=Color.White;try{config=PhoneDeskConfig.Load();}catch(Exception e){MessageBox.Show(e.Message+"\nDe bestaande instellingen blijven staan tot Opslaan.");config=new PhoneDeskConfiguration();}
 Controls.Add(new Label{Text="Phone Desk Settings",Font=new Font("Segoe UI",19,FontStyle.Bold),AutoSize=true,Left=22,Top=20});Controls.Add(new Label{Text="Kies drie telefoons tegelijk. Schaal 1,0 is de standaardgrootte.",AutoSize=true,Left=24,Top=65});string[] captions={"Phone Desk I","Phone Desk II","Phone Desk III","iPad Landscape","iPad Portrait"};
 for(int i=0;i<5;i++){int y=110+i*52;var p=config.Devices[i];enabled[i]=new CheckBox{Text=captions[i],Checked=p.Enabled,Left=24,Top=y+4,Width=150};models[i]=new ComboBox{Left=180,Top=y,Width=235,DropDownStyle=ComboBoxStyle.DropDownList};models[i].Items.AddRange(PhoneDeskConfig.Models);models[i].SelectedItem=p.Model;colors[i]=new ComboBox{Left=430,Top=y,Width=145,DropDownStyle=ComboBoxStyle.DropDownList};colors[i].Items.AddRange(PhoneDeskConfig.Colors);colors[i].SelectedItem=p.Color;scales[i]=new NumericUpDown{Left=595,Top=y,Width=100,DecimalPlaces=1,Increment=0.1m,Minimum=0.5m,Maximum=1.5m,Value=(decimal)p.Scale};Controls.Add(enabled[i]);Controls.Add(models[i]);Controls.Add(colors[i]);Controls.Add(scales[i]);}
 var save=new Button{Text="Opslaan en sluiten",Left=24,Top=395,Width=190,Height=42};save.Click+=(s,e)=>{if(Save())Close();};Controls.Add(save);var open=new Button{Text="Opslaan en toestellen openen",Left=230,Top=395,Width=270,Height=42};open.Click+=(s,e)=>{if(!Save())return;try{for(int i=0;i<5;i++)if(config.Devices[i].Enabled)Process.Start(new ProcessStartInfo(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,PhoneDeskConfig.Executables[i])){UseShellExecute=true});Close();}catch(Exception ex){MessageBox.Show(ex.Message,"Toestel openen mislukt");}};Controls.Add(open);}
 bool Save(){try{for(int i=0;i<5;i++)config.Devices[i]=new DeviceProfile{Model=(string)models[i].SelectedItem,Color=(string)colors[i].SelectedItem,Scale=(double)scales[i].Value,Enabled=enabled[i].Checked};PhoneDeskConfig.Save(config);return true;}catch(Exception e){MessageBox.Show(e.Message,"Opslaan mislukt");return false;}}
 [STAThread]static void Main(){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);Application.Run(new Pds());}
}
